<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {AutomationsClient,AutomationError,authorizationUrl,setupFields,type SetupField,type Connector,type Connection,type Draft,type Workflow,type Approval,type ApprovalDecision,type Configuration,type TestReceipt,type Execution,type Authorization,type ProviderSetup,type ConnectionOptions} from './automations-client';
 import AutomationConnectionCard from './AutomationConnectionCard.svelte';
 import AutomationInternalRun from './AutomationInternalRun.svelte';
 import AutomationSetupCard from './AutomationSetupCard.svelte';import AutomationReviewCard from './AutomationReviewCard.svelte';import AutomationApprovalCard from './AutomationApprovalCard.svelte';
 import CompanySmtpIntegrations from '../integrations/CompanySmtpIntegrations.svelte';
 import './automations.css';
 export let selectedBotId='';export let people:{id:string;name:string}[]=[];export let companyId:string;export let actorId:string;export let conversationId='';export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number};changed:{companyId:string;conversationId:string};openConversation:{conversationId:string}}>();
 let client:AutomationsClient|undefined,watched:AbortSignal|undefined,mounted=false,key='',generation=0,session='',room='';
 let tab:'automations'|'integrations'|'approvals'='automations',loading=true,busy=false,available=false,canManage=false,engineAvailable=false,error='',notice='';
 let setupProviders:ProviderSetup[]=[];
 let connectors:Connector[]=[],connections:Connection[]=[],drafts:Draft[]=[],workflows:Workflow[]=[],approvals:Approval[]=[],active:Draft|null=null,selectedWorkflow:Workflow|null=null;
 let test:TestReceipt|null=null,authorization:Authorization|null=null,authorizationProvider='',history:Execution[]|null=null,historyWorkflow:Workflow|null=null,disconnecting:Connection|null=null,creating=false,creatingIntent:'refund_request'|'internal_approval_test'='refund_request',supportedIntents:string[]=[],runReceipts:Record<string,string>={},name='',editing=false,editField:SetupField='requestSource',editValue='';
 $: if(mounted&&(key!==companyId+'\0'+actorId+'\0'+conversationId||watched!==accessSignal)){reset();key=companyId+'\0'+actorId+'\0'+conversationId;room=conversationId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new AutomationsClient(companyId,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);connectors=[];setupProviders=[];connections=[];drafts=[];workflows=[];approvals=[];active=null;selectedWorkflow=null;test=null;authorization=null;authorizationProvider='';history=null;historyWorkflow=null;disconnecting=null;creating=false;editing=false;editValue='';name='';available=false;canManage=false;engineAvailable=false;supportedIntents=[];runReceipts={};busy=false;error='';notice='';}
 function lost(){reset();loading=false;dispatch('close');}
 function fail(cause:unknown){if(cause instanceof AutomationError&&(cause.status===401||cause.status===403)){reset();loading=false;dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'Starli Automations could not be reached.';}
 async function load(){if(!client)return;const n=generation,current=client;loading=true;error='';try{const [catalog,connected,saved,savedApprovals,allWorkflows,setup]=await Promise.all([current.catalog(),current.connections(),room?current.drafts(room):Promise.resolve([]),room?current.approvals(room):Promise.resolve([]),current.workflows(),current.connectionSetup().catch(e=>{if(e instanceof AutomationError&&(e.status===401||e.status===403))throw e;return null;})]);if(n!==generation)return;connectors=catalog.connectors;setupProviders=setup?.providers||[];engineAvailable=catalog.engine.available;canManage=catalog.actions.canManage;supportedIntents=catalog.supportedIntents||['refund_request'];connections=connected;drafts=saved;approvals=savedApprovals;workflows=allWorkflows;available=true;if(active){active=drafts.find(d=>d.id===active?.id)||null;if(test&&active?.revision!==test.revision)test=null;}if(selectedWorkflow)selectedWorkflow=workflows.find(w=>w.id===selectedWorkflow?.id)||null;authorization=null;}catch(e){if(n===generation){available=false;fail(e);}}finally{if(n===generation)loading=false;}}
 async function run(task:()=>Promise<void>){if(busy)return;const n=generation;busy=true;error='';notice='';try{await task();if(n===generation)dispatch('changed',{companyId,conversationId:room});}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function store(draft:Draft){editing=false;editValue='';drafts=[...drafts.filter(d=>d.id!==draft.id),draft];active=draft;test=null;authorization=null;selectedWorkflow=null;}
 async function create(){if(!client||!room||!name.trim())return;const current=client,n=generation;await run(async()=>{const d=await current.create(room,name.trim(),creatingIntent==='internal_approval_test'?{requestSource:'starli',notifySlack:false}:{},selectedBotId||undefined,creatingIntent);if(n!==generation)return;store(d);name='';creating=false;notice='Draft saved in this conversation.';});}
 async function answer(configuration:Configuration){if(!client||!active)return;const current=client,draft=active,n=generation;await run(async()=>{const next=await current.answer(draft,configuration);if(n===generation)store(next);});}
 async function connect(providerId:string,draft:Draft|null=active,options:ConnectionOptions={}){if(!client||!room)return;const current=client,n=generation;await run(async()=>{const result=await current.authorize(providerId,room,draft||undefined,options);if(n!==generation)return;if(result.status==='CONNECTED'){await load();if(n===generation)notice='Existing company connection verified. Setup resumed.';return;}const setup=await current.connectionSetup().catch(e=>{if(e instanceof AutomationError&&(e.status===401||e.status===403))throw e;return null;});if(n!==generation)return;if(setup)setupProviders=setup.providers;authorization=result;authorizationProvider=providerId;if(result.status==='SETUP_UNAVAILABLE')notice='Secure connection setup is not yet available. Your saved workflow is retained.';});}
 async function disconnect(){if(!client||!disconnecting)return;const current=client,target=disconnecting,n=generation;await run(async()=>{await current.disconnect(target);if(n!==generation)return;disconnecting=null;await load();if(n===generation)notice='Company connection revoked. Future tasks must reconnect before using this account.';});}
 async function testDraft(draft:Draft){if(!client)return;const current=client,n=generation;await run(async()=>{const result=await current.test(draft);if(n!==generation)return;const saved=await current.drafts(draft.conversationId);if(n!==generation)return;drafts=saved;active=saved.find(d=>d.id===draft.id)||null;test=result;});}
 async function activate(draft:Draft){if(!client)return;const current=client,n=generation;await run(async()=>{const result=await current.activate(draft);if(n!==generation)return;workflows=[...workflows.filter(w=>w.id!==result.id),result];selectedWorkflow=result;active=null;notice=draft.summary.approvalRequired?'Automation activation confirmed. Per-action approval is still required.':'New-order notifications activated for the original conversation. No per-order approval is required.';});}
 async function runInternal(workflow:Workflow,label:string,key:string){if(!client)return;const current=client,n=generation;await run(async()=>{const receipt=await current.runInternal(workflow,label,key);if(n!==generation)return;runReceipts={...runReceipts,[workflow.id]:receipt.id};notice='Internal test submitted. Follow its exact approval and recorded receipt in the original conversation.';await load();});}
 async function resume(workflow:Workflow){if(!client)return;const current=client,n=generation;await run(async()=>{const result=await current.resume(workflow);if(n!==generation)return;workflows=workflows.map(w=>w.id===result.id?result:w);selectedWorkflow=result;notice=result.intent==='shopify_new_order_chat'?'New-order notifications resumed in the original conversation.':'Automation resume confirmed.';});}
 async function pause(workflow:Workflow){if(!client)return;const current=client,n=generation;await run(async()=>{const result=await current.pause(workflow);if(n!==generation)return;workflows=workflows.map(w=>w.id===result.id?result:w);selectedWorkflow=result;notice='Automation pause confirmed.';});}
 async function edit(item:Draft|Workflow){if(!client)return;if('configuration' in item){active=item;selectedWorkflow=null;test=null;editing=true;editField=(Object.keys(item.configuration).find(k=>setupFields.includes(k as SetupField)) as SetupField)||'requestSource';editValue=String(item.configuration[editField]??'');return;}const current=client,n=generation;await run(async()=>{const saved=await current.drafts(item.conversationId);if(n!==generation)return;const d=saved.find(v=>v.id===item.draftId);if(!d)throw new AutomationError(0,'This workflow’s saved draft is unavailable. Open its original conversation.');room=item.conversationId;drafts=saved;store(d);editing=true;editField=(Object.keys(d.configuration).find(k=>setupFields.includes(k as SetupField)) as SetupField)||'requestSource';editValue=String(d.configuration[editField]??'');dispatch('openConversation',{conversationId:room});});}
 async function saveEdit(){if(!active||!editValue.trim())return;await answer({[editField]:editField==='notifySlack'?editValue==='true':editValue.trim()} as Configuration);}
 async function showHistory(workflow:Workflow){if(!client)return;const current=client,n=generation;await run(async()=>{const values=await current.history(workflow);if(n===generation){history=values;historyWorkflow=workflow;}});}
 async function decide(approval:Approval,decision:ApprovalDecision){if(!client)return;const current=client,n=generation;await run(async()=>{const result=await current.decide(approval,decision);if(n!==generation)return;approvals=approvals.map(a=>a.id===result.id?result:a);notice='Decision recorded for this exact request. Check execution history for the outcome.';});}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}
 function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 function focused(){checkSession();if(client)void load();}
 const date=(n:number)=>new Date(n*1000).toLocaleString();
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);window.addEventListener('focus',focused);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);window.removeEventListener('focus',focused);});
</script>
<section class="starli-automations management" aria-label="Starli Automations and Integrations"><button class="back" on:click={()=>dispatch('close')}>← Back to workspace</button><header class="sa-heading"><div><span class="sa-eyebrow">COMPANY WORKSPACE</span><h1>Automations & integrations</h1><p class="sa-muted">Connect business apps. Build routines with your Starli bots.</p></div><button disabled={busy||loading} on:click={()=>void load()}>Refresh</button></header><nav aria-label="Automation sections"><button class:active={tab==='automations'} on:click={()=>tab='automations'}>Starli Automations</button><button class:active={tab==='integrations'} on:click={()=>tab='integrations'}>Starli Integrations</button><button class:active={tab==='approvals'} on:click={()=>tab='approvals'}>Approvals{approvals.filter(a=>a.status==='PENDING').length?' · '+approvals.filter(a=>a.status==='PENDING').length:''}</button></nav>
 {#if error}<div role="alert" class="sa-error">{error}</div>{/if}{#if notice}<p class="sa-muted" role="status">{notice}</p>{/if}
 {#if loading&&!available}<div class="sa-empty" role="status">Loading company automations…</div>{:else if !available}<div class="sa-empty"><h2>Starli Automations unavailable</h2><p class="sa-muted">The automation service is not available on this deployment. Your existing conversations are unaffected.</p><button on:click={()=>void load()}>Try again</button></div>{:else}
 {#if tab==='automations'}<div class="sa-heading section-heading"><div><h2>Workflows</h2><p class="sa-muted">Drafts stay with their original conversation. Activation and individual action approvals are separate.</p></div><div class="sa-actions"><button class="sa-primary" disabled={!canManage||!room||busy} on:click={()=>{creatingIntent='refund_request';creating=!creating;}}>New automation</button>{#if supportedIntents.includes('internal_approval_test')}<button disabled={!canManage||!room||!selectedBotId||busy} on:click={()=>{creatingIntent='internal_approval_test';name='Internal approval check';creating=true;}}>Create internal approval test</button>{/if}</div></div>{#if !room}<p class="sa-warning">Open this panel from a bot conversation to set up a new automation.</p>{/if}{#if !engineAvailable}<p class="sa-warning">Execution is not available yet. You can save and review workflow drafts; tests and activation follow the service’s readiness checks.</p>{/if}
 {#if creating}<form class="create-form" on:submit|preventDefault={create}><h3>{creatingIntent==='internal_approval_test'?'Internal approval check':'Refund request handling'}</h3><p class="sa-muted">{creatingIntent==='internal_approval_test'?'Run a real internal workflow, request human approval and record an internal test receipt. No external business action is performed.':'Set up order lookup, human review and the permitted refund or support-ticket branch.'}</p><label class="sa-label">Automation name<input class="sa-input" bind:value={name} maxlength="120" placeholder="Refund request handling" disabled={busy} required/></label><div class="sa-actions"><button type="button" disabled={busy} on:click={()=>creating=false}>Cancel</button><button class="sa-primary" disabled={busy||!name.trim()}>Save and continue</button></div></form>{/if}
 <form hidden={!editing||!active} class="create-form" on:submit|preventDefault={saveEdit}><h3>Edit saved configuration</h3><p class="sa-muted">Saving a change creates a new revision and invalidates previous test results.</p><label class="sa-label">Setting<select class="sa-input" bind:value={editField} on:change={()=>editValue=String(active?.configuration[editField]??'')} disabled={busy}>{#each setupFields.filter(f=>active?.configuration[f]!==undefined) as field}<option value={field}>{field.replace(/([A-Z])/g,' $1').toLowerCase()}</option>{/each}</select></label><label class="sa-label">New value{#if editField==='notifySlack'}<select class="sa-input" bind:value={editValue} disabled={busy}><option value="true">Notify in Slack</option><option value="false">Do not notify in Slack</option></select>{:else}<input class="sa-input" bind:value={editValue} maxlength="300" disabled={busy} required/>{/if}</label><div class="sa-actions"><button type="button" disabled={busy} on:click={()=>editing=false}>Cancel edit</button><button class="sa-primary" disabled={busy||!editValue.trim()}>Save revision</button></div></form>{#if active}<AutomationSetupCard draft={active} {setupProviders} {connectors} {people} {busy} {authorization} on:answer={e=>answer(e.detail)} on:connect={e=>connect(e.detail.providerId,active,{shopDomain:e.detail.shopDomain,expectedSetupRevision:e.detail.expectedSetupRevision})} on:refresh={()=>void load()}/><AutomationReviewCard draft={active} {test} {busy} {engineAvailable} on:test={e=>testDraft(e.detail)} on:activate={e=>activate(e.detail)} on:edit={e=>edit(e.detail)}/>{/if}
 {#if selectedWorkflow}<AutomationReviewCard workflow={selectedWorkflow} {busy} {engineAvailable} on:pause={e=>pause(e.detail)} on:resume={e=>resume(e.detail)} on:edit={e=>edit(e.detail)} on:history={e=>showHistory(e.detail)}/>{#if selectedWorkflow.intent==='internal_approval_test'&&selectedWorkflow.actions.canRun}<AutomationInternalRun workflow={selectedWorkflow} {busy} receiptId={runReceipts[selectedWorkflow.id]||''} on:run={e=>runInternal(e.detail.workflow,e.detail.label,e.detail.key)}/>{/if}{/if}
 {#if drafts.length}<h3 class="list-title">Saved drafts in this conversation</h3><div class="list">{#each drafts as draft}<button class="list-row" disabled={busy} on:click={()=>{active=draft;selectedWorkflow=null;test=null;authorization=null;}}><span><strong>{draft.name}</strong><small>{draft.missing.length?draft.missing.length+' setup requirement(s)':'Ready for review'} · revision {draft.revision}</small></span><span class="sa-badge">{draft.status.replaceAll('_',' ').toLowerCase()}</span></button>{/each}</div>{/if}<h3 class="list-title">Company automations</h3><div class="list">{#each workflows as workflow}<button class="list-row" disabled={busy} on:click={()=>{selectedWorkflow=workflow;active=null;test=null;authorization=null;}}><span><strong>{workflow.name}</strong><small>{workflow.summary.trigger} · revision {workflow.revision}</small></span><span class="sa-badge">{workflow.status.replaceAll('_',' ').toLowerCase()}</span></button>{:else}<div class="sa-empty"><h3>No active automations yet</h3><p class="sa-muted">Ask your bot to build a routine, or start a saved setup from this conversation.</p></div>{/each}</div>
 {#if history!==null&&historyWorkflow}<section class="history"><div class="sa-heading"><h3>{historyWorkflow.name} · History</h3><button on:click={()=>{history=null;historyWorkflow=null;}}>Close</button></div>{#each history as execution}<article><div class="sa-heading"><strong>{execution.status.replaceAll('_',' ').toLowerCase()}</strong><span class="sa-muted">{date(execution.createdAt)}</span></div><p class="sa-muted">Workflow version {execution.workflowVersion} · execution {execution.id}</p>{#if execution.receipt}<p class="sa-muted">{execution.receipt.operation} · {execution.receipt.resourceId} · {execution.receipt.status} · verified {date(execution.receipt.verifiedAt)}</p>{/if}{#if execution.errorCode}<p class="sa-warning">This execution needs review. Check the recorded outcome before retrying.</p>{/if}</article>{:else}<p class="sa-muted">No executions recorded. Tests do not perform external actions.</p>{/each}</section>{/if}
 {:else if tab==='integrations'}<div class="section-heading"><h2>Connected business apps</h2><p class="sa-muted">Company connections are authorized through secure provider sign-in. Passwords and tokens are never requested in chat.</p></div><div class="integration-grid">{#each connectors as connector}<article class="integration"><div class="sa-heading"><div class="sa-connect"><div class="sa-service-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="none"><rect x="4" y="4" width="6" height="6" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="14" y="4" width="6" height="6" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="4" y="14" width="6" height="6" rx="1.5" stroke="currentColor" stroke-width="1.5"/><rect x="14" y="14" width="6" height="6" rx="1.5" stroke="currentColor" stroke-width="1.5"/></svg></div><h3>{connector.displayName}</h3></div><span class="sa-badge">{connector.status==='AVAILABLE'?'Available':'Needs connection'}</span></div><p class="sa-muted">{connector.capabilities.length} reviewed capabilities</p>{#each connections.filter(c=>c.providerId===connector.id) as connection}<div class="connection"><strong>{connection.displayName}</strong><p class="sa-muted">{connection.accountIdentity} · {connection.status.toLowerCase()}</p><div class="sa-permissions">{#each connection.scopes as scope}<span>{scope}</span>{/each}</div>{#if canManage&&connection.status!=='REVOKED'}<button class="sa-danger" disabled={busy} on:click={()=>disconnecting=connection}>Disconnect</button>{#if disconnecting?.id===connection.id}<div class="sa-confirm"><strong>Disconnect this company account?</strong><p class="sa-muted">Bots and workflows using {connection.displayName} will lose access. Reconnecting requires secure authorization.</p><div class="sa-actions"><button disabled={busy} on:click={()=>disconnecting=null}>Keep connection</button><button class="sa-danger" disabled={busy} on:click={disconnect}>Confirm disconnect</button></div></div>{/if}{/if}</div>{/each}<div>{#if ['slack','shopify'].includes(connector.id)}<AutomationConnectionCard providerId={connector.id} providerName={connector.displayName} requestedScopes={[...new Set(connector.capabilities.flatMap(c=>c.requiredScopes))]} setup={setupProviders.find(s=>s.providerId===connector.id)||null} canManage={canManage&&!!room} {busy} authorization={authorizationProvider===connector.id?authorization:null} on:connect={e=>connect(e.detail.providerId,null,{shopDomain:e.detail.shopDomain,expectedSetupRevision:e.detail.expectedSetupRevision})} on:refresh={()=>void load()}/>{:else}<button disabled={!canManage||!room||busy} on:click={()=>connect(connector.id,null)}>Connect account</button>{/if}</div>{#if !['slack','shopify'].includes(connector.id)&&authorizationProvider===connector.id&&authorization}<p class="sa-warning">{authorization.status==='SETUP_UNAVAILABLE'?'Secure authorization is not available for this integration yet. Open a saved workflow setup when connection support is ready.':'Secure sign-in is ready.'}</p>{#if authorization.status==='AUTHORIZATION_REQUIRED'&&authorizationUrl(authorization.authorizationUrl)}<a class="sa-primary sa-link" href={authorizationUrl(authorization.authorizationUrl)||undefined} target="_blank" rel="noopener noreferrer">Continue secure sign-in ↗</a>{/if}{/if}</article>{:else}<div class="sa-empty"><p class="sa-muted">No business integrations are available on this deployment.</p></div>{/each}</div>{#if canManage}<CompanySmtpIntegrations {companyId} {actorId} {accessSignal} compact={true} on:denied={e=>dispatch('denied',e.detail)}/>{/if}
 {:else}<div class="section-heading"><h2>Action approvals</h2><p class="sa-muted">Canonical requests for this conversation. A decision through another connected notification resolves the same request.</p></div>{#each approvals as approval}<AutomationApprovalCard {people} {approval} {actorId} {busy} on:decision={e=>decide(e.detail.approval,e.detail.decision)}/>{:else}<div class="sa-empty"><h3>No approval requests</h3><p class="sa-muted">Requests will appear here when a workflow needs an authorized decision.</p></div>{/each}{/if}
 {/if}
</section>
<style>.management{width:100%;max-width:1100px;margin:0 auto;padding:36px 44px 70px;overflow:auto}.management .back{border:0;background:none;padding:0;color:#71809a;font-size:12px}.management header{margin:32px 0 20px}.management nav{display:flex;gap:22px;overflow:auto;border-bottom:1px solid #e6ebf4;margin-bottom:24px}.management nav button{border:0;border-radius:0;white-space:nowrap;background:none;padding:13px 0;color:#71809a;border-bottom:2px solid transparent}.management nav button.active{color:#3466f6;border-bottom-color:#3466f6}.section-heading{margin:22px 0}.create-form,.integration,.history{border:1px solid #e6ebf4;border-radius:12px;padding:22px;margin:20px 0}.list-title{margin:24px 0 13px!important}.list{border:1px solid #e6ebf4;border-radius:12px;overflow:hidden}.management .list-row{display:flex;align-items:center;justify-content:space-between;gap:15px;width:100%;border:0;border-bottom:1px solid #e6ebf4;border-radius:0;padding:17px 20px;text-align:left}.management .list-row:last-child{border-bottom:0}.list-row small{display:block;font-size:10px;color:#71809a;margin-top:6px;line-height:1.7}.list .sa-empty{border:0;margin:0}.integration-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.integration{margin:0;min-width:0}.integration .sa-connect{margin:0}.integration .sa-heading{align-items:center;flex-wrap:wrap}.integration .sa-muted{overflow-wrap:anywhere}.connection{border-top:1px solid #e6ebf4;padding-top:14px;margin-top:14px}.history article{border-top:1px solid #e6ebf4;margin-top:15px;padding-top:15px}.history article .sa-heading{align-items:center}.history article .sa-heading .sa-muted{font-size:10px}.history p{overflow-wrap:anywhere}@media(max-width:700px){.management{padding:26px 22px}.management h1{font-size:24px}.management header,.section-heading.sa-heading{flex-direction:column;align-items:flex-start}.integration-grid{grid-template-columns:1fr}.create-form,.integration,.history{padding:17px}.management nav{gap:18px}.management nav button{font-size:11px}.management .list-row{padding:15px;align-items:flex-start}.history article .sa-heading{flex-direction:column;gap:3px}}</style>
